head.script:
// 화면 리사이징

scwin.gLdMktTp;
scwin.gSchDate;

// 확인절차 대상서식_STF37720 - 유가에 해당
gDepCd = js_dep_cd;
gEmpNo = js_emp_no;
scwin.gLdMktTp = js_market;
scwin.vMKT_TP_CD;

///////// 2. 초기화 영역 /////////
/**
 * @method
 * @name onpageload
 * @description 화면 로딩 시 초기 처리 — init 순차 호출
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.onpageload = async function() {
    try {
        $c.cm.PanelToGroupBox(panel_1);
        panel_mkt.hide();
        rdo_MKT_ID.setValue('1');
        await scwin.search();
    } catch (ex) {
        await $c.exception.handleError(ex, { context : "ULDSTF37720.onpageload" });
    }
};

/**
 * @method
 * @name onpageunload
 * @description 화면 언로드 시 정리 처리
 * @returns {void}
 * @hidden N
 */
scwin.onpageunload = function() {
};

///////// 3. 컴포넌트 이벤트 영역 /////////
/**
 * @method
 * @name btn_Close_onclick
 * @description 「닫기」 클릭 이벤트
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.btn_Close_onclick = async function() {
    try {
        await $c.win.closePopup();
    } catch (ex) {
        await $c.exception.handleError(ex, { context : "ULDSTF37720.btn_Close_onclick" });
    }
};

/**
 * @method
 * @name dts_List_OnLoadCompleted
 * @description dts_List 로드 완료 후처리(레거시 Gauce 이벤트명 — 화면 내부 호출용)
 * @param {Number} rowcount 조회 건수
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.dts_List_OnLoadCompleted = async function(rowcount) {
    try {
        if (dts_List.errorMsg) {
            await $c.win.alert(dts_List.errorMsg);
        } else {
            $c.stf.fillGridHeaderTotalCnt(rowcount, panel_page);
        }
    } catch (ex) {
        await $c.exception.handleError(ex, { context : "ULDSTF37720.dts_List_OnLoadCompleted" });
    }
};

/**
 * @method
 * @name dts_List_OnLoadError
 * @description dts_List 로드 오류 처리(레거시 Gauce 이벤트명 — 화면 내부 호출용)
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.dts_List_OnLoadError = async function() {
    try {
        await $c.win.alert(dts_List);
    } catch (ex) {
        await $c.exception.handleError(ex, { context : "ULDSTF37720.dts_List_OnLoadError" });
    }
};

/**
 * @method
 * @name btn_Search_onclick
 * @description 「조회」 클릭 이벤트
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.btn_Search_onclick = async function() {
    try {
        await scwin.search();
    } catch (ex) {
        await $c.exception.handleError(ex, { context : "ULDSTF37720.btn_Search_onclick" });
    }
};

/**
 * @method
 * @name btn_Excel_onclick
 * @description 「엑셀다운로드」 클릭 이벤트
 * @returns {void}
 * @hidden N
 */
scwin.btn_Excel_onclick = function() {
    try {
        $c.stf.doLogSave('ULDSTF37720.xml', SCREN_PROCS_TP_CD_07, '');
        let sMsg = '';
        scwin.vMKT_TP_CD = rdo_MKT_ID.getValue();
        if (scwin.vMKT_TP_CD === '1') {
            sMsg = "확인절차  대상서식";
        } else {
            sMsg = "사전확인면제대상서식";
        }
        $c.data.downloadGridViewExcel(grd_Grid, {fileName: sMsg, type: "8"});
    } catch (ex) {
        $c.exception.handleError(ex, { context : "ULDSTF37720.btn_Excel_onclick" });
    }
};

/**
 * @method
 * @name txb_form_nm_onkeypress
 * @description txb_form_nm onkeypress 이벤트
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.txb_form_nm_onkeypress = async function() {
    try {
        if (window.event.keyCode === 13) {
            await scwin.search();
        }
    } catch (ex) {
        await $c.exception.handleError(ex, { context : "ULDSTF37720.txb_form_nm_onkeypress" });
    }
};

/**
 * @method
 * @name txb_form_cd_onkeypress
 * @description txb_form_cd onkeypress 이벤트
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.txb_form_cd_onkeypress = async function() {
    try {
        if (window.event.keyCode === 13) {
            await scwin.search();
        }
    } catch (ex) {
        await $c.exception.handleError(ex, { context : "ULDSTF37720.txb_form_cd_onkeypress" });
    }
};

///////// 4. 서브미션 콜백 영역 /////////
/**
 * @method
 * @name search
 * @description search 처리
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.search = async function() {
    scwin.vMKT_TP_CD = rdo_MKT_ID.getValue();
    const vFORM_CD = txb_form_cd.getValue();
    const vFORM_NM = txb_form_nm.getValue();
    url += "&MKT_TP_CD=" + scwin.vMKT_TP_CD;
    url += "&FORM_CD=" + vFORM_CD;
    url += "&FORM_NM=" + vFORM_NM;
    url += "&SCREN_ID=" + 'ULDSTF37720.xml';
    url += "&SCREN_PROCES_TP_CD=" + SCREN_PROCS_TP_CD_01;
    const sbmOptions = {
        id : "sbm_dts_List",
        action : "/ByPass.do",
        ref : "",
        target : "dts_List=body.content",
        isProcessMsg : false
    };

    const sbmRtn = await $c.sbm.executeDynamic(sbmOptions);
    // TODO Stage2: sbmRtn 응답 처리 로직 작성 (구 submitDoneHandler 자리)

};
